# ============ BOT HANDLERLARI ============

async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await update.message.reply_text(
        "👋 Assalomu alaykum!\n\n"
        "📚 *Tashkiliy Xulq* fanidan test botiga xush kelibsiz!\n\n"
        "🎯 Har testda 20 ta savol beriladi\n"
        "✅ To'g'ri javob yashil belgilanadi\n"
        "❌ Noto'g'ri javobda to'g'ri javob ko'rsatiladi\n\n"
        "Boshlash uchun /test buyrug'ini yuboring!",
        parse_mode="Markdown"
    )

async def test_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    selected = random.sample(QUESTIONS, QUESTIONS_PER_TEST)
    context.user_data['questions'] = selected
    context.user_data['current'] = 0
    context.user_data['score'] = 0
    await send_question(update, context)

async def send_question(update: Update, context: ContextTypes.DEFAULT_TYPE):
    questions = context.user_data['questions']
    idx = context.user_data['current']
    q = questions[idx]

    letters = ['A', 'B', 'C', 'D']
    keyboard = [
        [InlineKeyboardButton(f"{letters[i]}) {a[:50]}{'...' if len(a)>50 else ''}", callback_data=str(i))]
        for i, a in enumerate(q['answers'])
    ]
    reply_markup = InlineKeyboardMarkup(keyboard)

    text = f"❓ *Savol {idx+1}/{QUESTIONS_PER_TEST}*\n\n{q['question']}"

    if update.callback_query:
        await update.callback_query.message.reply_text(text, reply_markup=reply_markup, parse_mode="Markdown")
    else:
        await update.message.reply_text(text, reply_markup=reply_markup, parse_mode="Markdown")

async def handle_answer(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()

    if 'questions' not in context.user_data:
        await query.message.reply_text("Yangi test boshlash uchun /test yuboring.")
        return

    chosen = int(query.data)
    questions = context.user_data['questions']
    idx = context.user_data['current']
    q = questions[idx]
    correct = q['correct']
    letters = ['A', 'B', 'C', 'D']

    if chosen == correct:
        context.user_data['score'] += 1
        result_text = f"✅ *To'g'ri!*\n\n📌 {q['answers'][correct]}"
    else:
        result_text = (
            f"❌ *Noto'g'ri!*\n\n"
            f"Siz tanladingiz: {letters[chosen]}) {q['answers'][chosen]}\n\n"
            f"✅ To'g'ri javob: {letters[correct]}) {q['answers'][correct]}"
        )

    await query.message.edit_reply_markup(reply_markup=None)
    context.user_data['current'] += 1

    if context.user_data['current'] >= QUESTIONS_PER_TEST:
        score = context.user_data['score']
        total = QUESTIONS_PER_TEST
        percent = int(score / total * 100)

        if percent >= 86:
            baho = "5 (A'lo) 🏆"
        elif percent >= 71:
            baho = "4 (Yaxshi) 👍"
        elif percent >= 56:
            baho = "3 (Qoniqarli) 😐"
        else:
            baho = "2 (Qoniqarsiz) ❗"

        await query.message.reply_text(result_text, parse_mode="Markdown")
        await query.message.reply_text(
            f"🏁 *Test yakunlandi!*\n\n"
            f"✅ To'g'ri: {score}/{total}\n"
            f"📊 Foiz: {percent}%\n"
            f"📝 Baho: {baho}\n\n"
            f"Qayta urinish uchun /test yuboring!",
            parse_mode="Markdown"
        )
        context.user_data.clear()
    else:
        await query.message.reply_text(result_text, parse_mode="Markdown")
        await send_question(update, context)

def main():
    app = Application.builder().token(TOKEN).build()
    app.add_handler(CommandHandler("start", start))
    app.add_handler(CommandHandler("test", test_start))
    app.add_handler(CallbackQueryHandler(handle_answer))
    print("✅ Bot ishga tushdi!")
    app.run_polling()

if __name__ == "__main__":
    main()
